/**
 * The private-project rule as a predicate: rows the viewer may see are every
 * `org`/`public` project, plus `private` ones the viewer leads or was added to.
 * Callers decide whether the rule applies at all; this only expresses it.
 */
export function visibleProjectsPredicate(
  orgId: OrgId,
  viewerId: UserId,
): SQL | undefined {
  return and(
