      await expect(issueService.getBoard(actor, org.id, project.id)).rejects.toBeInstanceOf(NotFoundError);
      await expect(commentService.getThread(actor, org.id, issue.id)).rejects.toBeInstanceOf(NotFoundError);
      await expect(commentService.createComment(actor, {
        orgId: org.id, issueId: issue.id, body: "x", parentId: null, mentionedUserIds: [],
      })).rejects.toBeInstanceOf(NotFoundError);
      await expect(commentService.updateComment(actor, { orgId: org.id, commentId: comment.id, body: "y" })).rejects.toBeInstanceOf(NotFoundError);
      await expect(commentService.deleteComment(actor, { orgId: org.id, commentId: comment.id })).rejects.toBeInstanceOf(NotFoundError);
      await expect(issueService.changeIssueStatus(actor, { orgId: org.id, issueId: issue.id, status: "done" } as never)).rejects.toBeInstanceOf(NotFoundError);
      await expect(issueService.createIssue(actor, issueInput(org.id, project.id, { title: "nope" }))).rejects.toBeInstanceOf(NotFoundError);
      await expect(projectService.updateProject(actor, { orgId: org.id, projectId: project.id, name: "Renamed" } as never)).rejects.toBeInstanceOf(NotFoundError);
      await expect(projectService.archiveProject(actor, { orgId: org.id, projectId: project.id, archiveIssues: true } as never)).rejects.toBeInstanceOf(NotFoundError);

      const list = await projectService.listProjects(actor, { orgId: org.id, limit: 10, cursor: null } as never);
      expect(list.items.map((i) => i.project.id)).not.toContain(project.id);
      expect(list.total).toBe(0);

      const issues = await issueService.listIssues(actor, { orgId: org.id, limit: 10, cursor: null } as never);
      expect(issues.items).toHaveLength(0);
      expect(issues.total).toBe(0);
    }

    // Unchanged state after the refused writes.
    const stored = await issueRepo.findIssueById(org.id, issue.id);
    expect(stored?.status).toBe("backlog");
    expect(stored?.title).toBe("secret");

    // Lead (owner), admin: visible.
    for (const actor of [actors.owner, actors.admin]) {
      await expect(projectService.getProject(actor, org.id, "platform")).resolves.toBeTruthy();
      const issues = await issueService.listIssues(actor, { orgId: org.id, limit: 10, cursor: null } as never);
      expect(issues.total).toBe(1);
    }

    // Added project member: visible from then on.
    await projectMemberRepo.addProjectMember(org.id, project.id, userIds.member);
    await expect(projectService.getProject(actors.member, org.id, "platform")).resolves.toBeTruthy();
    await expect(issueService.getIssue(actors.member, org.id, issue.id)).resolves.toBeTruthy();
    const memberList = await projectService.listProjects(actors.member, { orgId: org.id, limit: 10, cursor: null } as never);
    expect(memberList.total).toBe(1);
    expect(await projectService.canViewProject(actors.viewer, (await projectService.getProject(actors.owner, org.id, "platform")).project)).toBe(true);

    // Removed member: hidden again.
    await projectMemberRepo.removeProjectMember(org.id, project.id, userIds.member);
    await expect(projectService.getProject(actors.member, org.id, "platform")).rejects.toBeInstanceOf(NotFoundError);

    // Lead change takes effect immediately.
    await projectService.updateProject(actors.admin, { orgId: org.id, projectId: project.id, leadId: userIds.viewer } as never);
    await expect(projectService.getProject(actors.viewer, org.id, "platform")).resolves.toBeTruthy();
    await expect(projectService.getProject(actors.owner, org.id, "platform")).resolves.toBeTruthy(); // owner role still sees all
  });

  it("platform staff sees a private project; canViewProject is false cross-tenant", async () => {
    const t = await createTenant("vis2", "growth");
    const { org, project, actors } = t;
    await projectService.updateProject(actors.admin, { orgId: org.id, projectId: project.id, visibility: "private" } as never);

    const staff = { ...actors.viewer, isPlatformStaff: true };
    await expect(projectService.getProject(staff, org.id, "platform")).resolves.toBeTruthy();

    const other = await createTenant("vis3", "growth");
    expect(await projectService.canViewProject(other.actors.owner, { ...project, orgId: other.org.id } as never)).toBe(false);
  });

  it("org and public projects stay visible to plain members", async () => {
    const t = await createTenant("vis4", "growth");
    const { org, project, actors } = t;
    await projectService.updateProject(actors.admin, { orgId: org.id, projectId: project.id, visibility: "public" } as never);
    await expect(projectService.getProject(actors.viewer, org.id, "platform")).resolves.toBeTruthy();
    await projectService.updateProject(actors.admin, { orgId: org.id, projectId: project.id, visibility: "org" } as never);
    await expect(projectService.getProject(actors.viewer, org.id, "platform")).resolves.toBeTruthy();
  });
});
